namespace OpenTPW.UI.Original;

/// <summary>
/// Register of every UI value or rule that is not taken from original data or hard evidence
/// (docs/UI.md "Approximation register"). Each site carries a matching
/// <c>// [APPROX:UI-NNN]</c> comment; <see cref="LogOnce"/> reports them at startup.
/// </summary>
public static class UiApproximations
{
	public static readonly IReadOnlyList<(string Id, string Assumption, string EvidenceNeeded)> All = new[]
	{
		("UI-003", "button/arm state frames drawn at the root node pose; child translations ignored; the control's model setter 0x65d070 (model at +0x98, model vtable +0xc with 0x57, then +0x14) is found, the node walk that submits the triangles is not", "the node walk of the PC UI model draw (the selected state mesh -> local matrix -> ancestor composition), or a capture of a button whose state child is offset"),
		("UI-004", "UI model triangles drawn back to front by Z, grouped per texture; the original's display object divides its depth buffer into a UI range in front of a linear and a log range (the dump 0x5833c0 prints [+0x48] begin, [+0x4c] ui end / linear begin, [+0x50] linear end / log begin, [+0x54] log end; the buffer itself is enabled or not, strings 0x768988 and 0x768958), which suggests depth-tested rather than sorted UI parts, not shown for the UI model draw; the device init 0x573080 sets ZENABLE 1, ZFUNC LESSEQUAL (4) and ZWRITEENABLE 1 when the display object's flag +0x88 bit 0x10 is set and ZENABLE and ZWRITEENABLE 0 otherwise, so a UI part is depth-tested when the buffer is on, but the UI draw's own state and order are not found", "the UI model draw call (which per-draw depth state and which order it submits) and the writer of the four range floats +0x48..+0x54"),
		("UI-006", "text colours: window titles and the lobby island name yellow, the object windows' labels and values white, the pause menu's lines cyan (white while focused), green values elsewhere, grey disabled, shadow and backdrop colours (the video's 720p chroma is good to about +-15 per channel); the original gives each text control an RGBA colour (0x65c5d5 → renderer +0x48, kept as ARGB at +0x78, 0x48fd07) and renders its glyphs white (0x48fa96) unless the control keeps the font's own colours (+0xdd); the values traced are the options labels' (0,0,0,255) (0x4a441e, UI-037), the buy list rows' (255,255,255,255) (0x4ad340), the pause menu lines' (0,175,190,255) (0x48b2b9) and the shared title colour (234,239,102,255) (0x492d20, fifteen window builders), with the lobby island name's second line (252,232,7,255) (0x4b8604) and a list row control that turns (140,0,60) on message 0x403 with a negative argument (0x4a0710); about a hundred more 0x65c5d5 calls (white, black, red (255,0,0) and (224,86,86) in the 0x4aa480 window) are not yet assigned to screens", "which screen each remaining 0x65c5d5 call colours (values, disabled states, costs) and the backdrop colours"),
		("UI-007", "one-pixel (×UI scale) drop shadow under UI text; the original's control text renderer (0x48f830) lays each string out and draws it once (one 0x6ae0f0 call into the control's bitmap), so its controls have no drop shadow; the whole glyph layout and draw library has one draw entry, 0x6ae0f0, whose only caller is the text box routine 0x492750 (three callers, each calling it once: the label and list text of 0x4a84c0 through 0x492c40, 0x480810 through 0x47fcd0 and 0x480460, 0x480570 through 0x47fe90; 0x6ae1c0 is the measure entry used by 0x4929f0), no offset or second pass exists there, and the BF4 glyphs carry only 0-15 coverage samples (docs/BF4-FONTS.md), so no shadow is baked into the font art; the capture's apparent shadow is not explained, and the vtable-reached control renderer 0x48f830 and the sprite blit of its bitmap (0x48f410) are not shown to add one", "the sprite draw of a text control's bitmap (0x48f410 → 0x588c20) and whether a capture's shadow is a render-state effect (UI-037)"),
		("UI-008", "text buttons on purple_button art: each half is one end cap, drawn with its mirror image; upper half normal, lower half focused/pressed", "capture of the original front-end buttons"),
		("UI-013", "the confirm dialog follows table 0x7583e8, the game-mode screen the name dialog 0x753f50 and the load screen the load dialog 0x7523f0, whose rows show the park's name and, right-aligned, the save file's local date and time as 0x49ec80 formats them (UITEXT 0x1c0 with day, month and year, then \" %02d:%02d\"; shipped parks and the sandbox have no file time and show none); the lobby's and the park's pause menus lay out their lines as 0x48c150 → 0x492f60 does (text width + 1 and height + 5 pixels on the canvas, centred, from top 10, 5 units apart), but the height follows OpenTPW's menu font tier ([EXT:ui-font-tier-by-scale]) with its text layout box standing in for the measure 0x4929f0, the online state's top of 0 (FUN_005b6450) is not followed and the focused line turns plain white at once instead of the original's ramp: the line procedure 0x48b2a0 starts it on message 0x10001 (read as the pointer entering) and 0x48b220 steps it on every message 0x1e, once per drawn frame (eight frames at the 60 Hz reference, [EXT:frame-driven-at-60hz]), from grey 0x21 in steps of 0x20 to white, then idle, while message 0x10002 restores (0, 175, 190)", "the measure 0x4929f0, and a capture of the ramp (what 0x10001 and 0x10002 are is read, not confirmed)"),
		("UI-018", "the lobby backdrop is painted flat with the cloud layer's eased colour (red toward the blue target) as a stand-in: the original clears to the fog colour 0x44DDFF and tints only its cloud layer (the engine sky's sky.tga, coloured from that grid), which is not drawn, nor is the scene's fog; two settings gate the eased colour and the flying-mesh count share, all in the .bss settings block 0x785840-0x785920 filled at runtime ([0x785888] > 1 and the options word 0x78d8d8 == 1 assumed to pass, as the capture's tinted clouds show; [0x7858dc] assumed 100 %, the video's flocks cannot be counted at 720p); an island without SKYCOLOUR gets black instead of the random target its constructor draws (0x5dfb4a-0x5dfb7b, three CRT rand() calls per island); the island clips are picked by a local stand-in for the C runtime's rand(); while the globe is up the lobby's flyers and island clips hold still (the original's behaviour there is not traced); the enter sequence is built (the camera turns to the island angle + π, the gate plays M1, the camera zooms under the black fade and the park starts below radius 8, 0x5e0490 states 1 and 2; an early leave's gate M2 close, 0x5e1350, is not reachable from the front end here); the key-unlock sequence is not traced; the lightning flash is not drawn (the capture shows none)", "the engine sky's draw (0x585ee0-0x586a00) and fog, the runtime contents of the settings block 0x785840-0x785920 and the options word 0x78d8d8, the lobby's subsystems while the globe is up, the key-award animation's code"),
		("UI-024", "the object windows (tables 0x755150, 0x755908, 0x755e80) draw their controls at the table rectangles, but the preview is OpenTPW's orthographic icon; the shop and sideshow customer satisfaction gauges (0x4e1e30 over a 30-entry history at +0x3bc, which OpenTPW's guests do not keep) are not simulated and draw empty; the local happiness gauge counts the guests on park cells at the object's anchor cell where 0x4cd880 walks the thing lists of the cells around the thing's own cell; the build window fits the preview size to translated names and prices", "the satisfaction history"),
		("UI-025", "the message tube holds up to five messages (the most the video shows) and drops the oldest on overflow, where the original's tube has eight 24-byte slots (insert 0x59a940; a message is admitted by 0x59abc0 under a per-type cap, 0x59c320, from the registry 0x76e300) and, with every slot full, replaces the lowest-priority slot only when that priority is lower than its own and is otherwise dropped; pending messages are not saved with the park, as in the original (its MESS chunk, 0x40fc80, holds only the 29 category id sets); the panel's rectangles are table 0x7501a0; its action buttons take the mb_ model of their kind (the original's table 0x48e610: kinds 3 and 4 mb_locate, 9 to 0x11 mb_buy, 0x12 b_loan, 0x13 mb_resrch, 0x14 b_pkinfo, 0x15 b_staffcost, 0x17 mb_callmech, 0x18 b_entry, 0x1a mb_accept, 0x1b mb_decline), but only the challenge offers carry actions (Accept and Decline) here and the other kinds' events are not ported; the strike messages (TAG_SYSTEM.str) and the challenge offers use the tube; its red body and white icons are OpenTPW's art ([EXT:message-tube-art]), an unanswered offer that was deleted is posted again ([EXT:challenge-offer-repost]) and OpenTPW's own feedback lines stay in a status line ([EXT:status-line])", "the registry's per-type caps and priorities (filled at run time, the loader 0x50af78 is not traced) and whether the tube draws eight icons"),
		("UI-026", "build icons: the preview model (P<name>.MD2, else the main model) is drawn by OpenTPW's CPU projection ([EXT:preview-icon-cpu-projection]); the buy window takes the original's 45° tilt (0x468e50), its turn of 0.0004 rad a millisecond that runs on across selections (0x46908a, 0x468e2f) and its fit (0x4689f0), but the original draws the preview through its 3D object pipeline (the ride object made by 0x463060 with a world matrix that 0x468e50 rebuilds each frame: the yaw and the ±π/4 tilt through the sine table, the matrix's x column scaled by 0.75 and its depth column by 0.1, then offsets) and starts the model's animation 5 (0x4732a0) and draws the footprint grid of the selected item (8×8 cells coloured by cell type) in control 0x1eb (0x4ab1b0), which OpenTPW does not; the object windows' previews keep a 30° tilt and 0.8 rad/s; sign faces use the object's rendered sign textures (ObjectSigns)", "the camera and projection the 3D pipeline draws the preview object with, the offset terms of 0x468e50 and the meaning of animation 5"),
		("UI-027", "a park click selects the object occupying the cell of the cursor's terrain hit (TerrainRayPick: 0x45bf90's heightfield triangles, the cell 0x45d560); the original selects a ride, shop or other object by its pick sprite: the sprite pass 0x5890e0 picks the nearest sprite flagged 0x200 under the cursor (a circle round its projected anchor), 0x532bd0 finds its owner among the things of the 3 x 3 cells round the hovered cell (types 1, 4 to 8 and 0x12), the hover handler 0x486d90 turns a hovered type 5, 4, 6, 7 or 8 into cursor mode 8, 9, 0xa, 0xb or 0xc and the click dispatcher 0x4879d0 opens the object window 0x4b6080 for it, only outside the visitor pick state (Shift alone or the visitor locator panel out); the ray's object hit [0x7a1cd4] selects nothing: its only readers copy it to the camera control block 0x79c6ac (0x443aab, 0x443d23)", "which model instances carry a pickable sprite (flag 0x200; the instance word +0x114 that 0x475ef0 tests) and that sprite's position, size and scale, to build the sprite pick for objects; the object half of the ray pick (RIDES-021)"),
		("UI-031", "exactly Ctrl at the placing click keeps the build tool armed (0x5253b8) and at the last click of a ride's queue re-arms it, the tool's angle returns to 0 when it is left (0x52f3b6); the coaster and water-track tools, whose original sub-modes are not traced, end the build tool whatever the modifier; the Ctrl word 0xC at 0x5259e2/0x5259f4 is Ctrl alone (the modifier builder 0x46b420: Shift 3, Ctrl 0xC, Alt 0x30) and a placement that 0x52fab0 reports as entrance-bearing (the sub-record flag +0x40) takes the tail 0x5259cf: the angle returns to 0x80, an item record with +0x29c = 1 ends the tool through 0x52f200 whatever the modifier, otherwise Ctrl alone keeps it (0x525a06) and any other word runs 0x52f1b0, which only shifts the mode history; which OpenTPW placements are those is not mapped; Level.PlaceObject owns purchase/guest linkage and its removal handler owns scrap credits", "the coaster sub-mode's continuation and the predicate that selects the 0x5259cf tail (what record +0x29c = 1 stands for)"),
		("UI-032", "catalogue names greedily wrap in their slots; the original's formatter (0x6aec80) wraps greedily: a line ends at the last break opportunity (glyph flag 0x10) before the glyph that overflows the width, dropping trailing spaces (flag 2), or before that glyph when the line has none; longer single-line labels fall back to the small font ([EXT:fit-button-text])", "which characters the formatter flags as break opportunities and spaces, and whether the catalogue slots are multi-line text controls"),
		("UI-034", "a fully opaque texture on a transparent (flag 0x2) model slot keys out black with a soft edge: transparent up to channel 6, opaque from 48, alpha ramped and colour un-premultiplied between (only ipan in the lobby f_lobbutbg panel); the texture state routine 0x567c10 sets an alpha test, an alpha reference and blend factors from the record flag bits (mask 0x556), but that its record flag 0x2 is the slot's flag 0x2 is not shown", "the original's render state for flagged texture slots (whether the record flag in 0x567c10 is the slot flag, and the colour-key handling of an opaque texture)"),
		("UI-036", "options slider: ball centre moves linearly over the track for value index 0..steps-1; click/drag sets the nearest step (OpenTPW's own steps, [EXT:options-slider-steps]); the original's slider class (vtable 0x705b20) places the thumb at track left + (value - min) × (track width - thumb width) / (max - min) in integer units (0x66b088), sets the value from a drag as min + the truncated (thumb left - track left) × (max - min) / (track width - thumb width) (0x66af19), moves one page (+0x148, default 1 from 0x66adc9) toward a click on the track (0x66b8aa) and one step on its arrows (message 0x100) or by the wheel delta (0x1000d); the options page gives its sliders the range 0..100 (0x4a455a) and sets the resolution and quality sliders to index × 50 (0x4a3d02, 0x4a3d23); the options page's change handler (0x4a2e90) turns the slider value v into the resolution index (v × 2) / 100 (0x423b60) and the quality index (k × v) / 100 with k 2, or 1 while the options word 0x78d8d8 is 0 (0x423ba0), and passes the music, effects and speech sliders on as the raw 0..100 volume (0x51bba0, 0x51bb80, 0x51bbc0, 0x423b40) without snapping the knob", "the knob's position after a drag for the 0..100 volume sliders and what a track click does there"),
		("UI-037", "option bar label colour (16,16,48), no drop shadow; the original's options labels (0x4a43b0) and slider labels (0x4a4490) are text controls given the colour (0,0,0,255) (0x4a441e, 0x4a44fe) and font slot 6 ([0x7537b4]) and drawn once without a shadow (0x48f830); how the control's colour reaches the white glyph bitmap (0x48fa96) when it is drawn is not traced, so the capture's near-black is kept", "the sprite draw of the control's text bitmap (0x48f410 → 0x588c20) and whether it tints with the colour at +0x78"),
		("UI-039", "option label size follows OpenTPW's fit rule ([EXT:option-label-fit]: letter box about 58 % of the label rectangle height, shared per page, a label whose widest value does not fit drops alone to the largest size that does); the original's options labels take font slot 6 of the bank ([0x7537b4], 0x4a443c: GAME5AA/GAME7/GAME8/GAME9 for banks 0-3) and their setup (0x4a43b0) does no fitting", "what the original does with a label that overflows (UI-032)"),
		("UI-041", "Load Park takes no game type from the loaded park: the original derives GameType from flag bits 0x2000000/0x1000000 of 0x7a1a8c (0x550ca0), set by a front-end toggle (0x4bbf63), and the Mac saves none with a park", "whether a park file of the PC build can carry the game type (not traced)"),
		("UI-042", "the camera button's slide-out panel (table 0x751720) slides in and out as the arm drawer 0x4a14f0 does (ten 20 ms steps, cat_ui 0x1C and 0xC2, help 0x131), but its slide ends at the table rectangle where the original's positions come from the HUD arm window ([0x7cb2b8], its child 0x21 found at 0x4a1b35) and the arm: the arithmetic of 0x4a1613-0x4a1650 starts the panel at the arm's left less the HUD window rectangle's width and 50, centres it on the arm and puts its top 50 units above the HUD window's top (read from the instructions, medium confidence; the end position is not resolved); the camcorder button arms the C-key walk ([EXT:camcorder-first-person]) where the original's button 99 enters the camcorder at once (0x498ad0 → 0x481a10), and the walk's movement and look controls are not traced (the original's eye is terrain + 5 units, 0x42b1c0); the postcard window (table 0x7540d8) keeps its photo frame empty and its preview and address book buttons disabled (the 640×240 camcorder photo 0x4a9280, the preview redraw 0x4a84c0 and the address book 0x4a8140 are not ported); the view cycle is a third button ([EXT:camera-view-cycle])", "the HUD window's rectangle; the walk's key bindings (action table 0x787c14) and the time unit of its turn step; the photo, its preview and the address book"),
		("UI-046", "the gauge bars (buy, ride, shop and sideshow windows) take the original's values and shape: the integer (value << 10) / 100 of a 0..1024 range (0x4abb00, 0x4ade40), a bar of the control's cell less 10 units top and bottom (0x485e30) that shows the art cut off at the value with the rest of the cell the track (0x478400: ridestatbar.wct's top 16 texel rows the bar, its bottom 16 the track); the colours of the bar and the track are read off the 720p video (a 70 % bar runs red, orange, yellow to lime green) because the decoded art's colours (now that the chroma decode is fixed, a red-orange start running to green) were not matched against the video", "the gauge sprite's colours as the original draws them (the draw of 0x477ff0, which would let the sprite replace the video-read ramp)"),
		("UI-047", "which OpenTPW tool state corresponds to the mode-object types that show control 48: type 3 (the tool-mode object, vtable 0x6fe9e0) wraps every build tool, so the held blueprint's price, the path or queue line's cost so far and the coaster track segment under the cursor show it; type 8 is the coaster panel's mode object (vtable 0x6feaa0, built by 0x46cfc0 when a panel button is pressed, 0x497bc0), which shows it only while bit 0 of 0x79c658 is set (0x447990; set at 0x441a5d), a placement-in-progress state OpenTPW does not track for the coaster tool (the bit is set at 0x441a5d when (flags & 0x3f) is 0 and cleared by the second action, 0x441a00; medium confidence), so OpenTPW shows the coaster cost in every sub-mode; no mode-object class returns type 4 (the classes 0x6fe980-0x6fead0 return 7, 3, 1, 5, 6, 8 and 9; 5 and 6 are the staff place and carry tools), and the staff and patrol tools show nothing", "which OpenTPW coaster tool state corresponds to the placement-in-progress bit of 0x79c658, and the class that returns type 4"),
		("UI-050", "the buy list's third column draws a tick box per row, ticked when the park owns at least one of the item; the box and the tick are drawn with rectangles and strokes in the video's colours, not the original's art (i_boxtick.MD2 holds only the empty box); the original's row cell 0x4ad340 sets the model i_boxtick (0x755144) on a child, and the owned state is 1 for an owned count of at least one (0x4d3d80, populate 0x4aaf70), else 2 for the first three items of a category (0x4caa70), else 0 (stored through 0x66403b), but what each state draws is not read", "the handler that turns the cell state into a frame (the message 0xc00 path) and the frames of i_boxtick"),
		("UI-051", "the ticket counter is the park's available tickets, where the original shows the player's earned tickets less the spent count (0x5af5d0), because OpenTPW's park keeps its own spent count and never moves the player ledger's, where the original's purchase check 0x4d4ad0 calls 0x5af740, which adds the cost to the player's spent count (+0x1c) when 0x5b1930 passes; the key counter is the ledger's (0x5af680, matched)", "routing the park's ticket purchases into the player ledger (a design decision: the ledger is optional and absent in the sandbox and Instant Action)"),
		("UI-060", "finance graph: the eight series' colours (the records of 0x499f30), their order and the selection masks (0x49a2e0: the bank balance and the park value clear the six cash-flow series, a cash-flow series clears the pair), the ten-division scale from min(0, lowest sample) to max(0, highest) (0x47fb30) and the default series (the bank balance, word 0x751fa0 = 1) follow tp.exe; the line style (two-unit strokes, grid lines, point marks) and the one-unit scale OpenTPW gives a flat range are OpenTPW's", "the original's graph drawer 0x47fe90 (stroke style, grid, point marks) and its empty or flat range"),
		("UI-064", "the research workload knob is the original's slider: values 1023 (top) to 0 (bottom), a limit of ((100 - c) / 3 + c) x 1024 / (MaxResearchersInPark x the grade-4 ResearchAbility) from the researchers' summed ability c, a workload of 70 + 30 x value / limit and the ball's travel (0x4a96b0, 0x4aac80, 0x66b088); a drag that starts on the ball moves it by the pointer's movement, clamped to the track, as 0x66b771 does; the knob's child 0xd2d12 (set to the limit) and 0xd2d11 (state (2 x step) / 7) are not drawn; the slider's ball proc 0x66bb9b moves the ball by the pointer's offset from the press point (stored per button at 0x10005 in 0xfaa59a/0xfaa59c) from the rectangle saved at the press or release (0x65cf3d), clamped to the track by 0x66b771, then reads the value back with 0x66af19, and a press in the track outside the ball puts the ball's centre under the pointer where the slider class pages by its step (0x66b8aa, 0x66b088 with the page word +0x148, whose value is not found)", "what 0xd2d12 and 0xd2d11 draw, the page step of a press in the track, and whether the saved rectangle is the press-time ball"),
		("UI-081", "applicant details: the skill gauge is a type-9 gauge set to the candidate's grade byte (+8, written by 0x507600 as AvgGradeOf* + R % 3 - 1 stored as 4 when above 4, OpenTPW's Grade) x 1024 / 5 (0x49b8e2) of its 0..1024 range (0x66d885 clamps), so a grade-0 candidate's value is 0; OpenTPW fills (Grade + 1) / 5 because the video's cheapest ($60) candidate shows about a fifth (12:00); the gauge models crop their art to value × 100 / 1024 per cent (UI-046), so a byte of 0 draws an empty bar and the fifth is not explained by the drawing", "which byte the video's cheapest candidate holds (the writer 0x507600 stores AvgGradeOf* + R % 3 - 1 as a byte, a wrapped 0xff becoming 4)"),
		("UI-082", "the hire window's figure is drawn one sprite pixel to 3.2 canvas units (640 pixels across the 2048-unit canvas), where the original sets its register 8 to 8.0 (0x004755D0, the scale 0x00542010 copies to the draw record +0x2C, default 1.0; the record slot 8 is +0xA4, the X scale, +0xA8 the second scale, both default 1.0); how the screen-sprite path (flag 0x40000, list 0x0087692C, count 0x875864) turns that scale into pixels is not traced: the list and its snapshot 0x876424 have no reader by absolute address, so the code that consumes them is not found; the figure also shows for an employee selected in the employed view, where 0x49BA00 reads only the applicant pool (0x507BD0, 32 entries of 0x14 bytes)", "the engine's screen-sprite quad size, or a capture of the hire window and of the employed view"),
		("UI-086", "paths, queues and unowned land take the original's records (classes 10 to 12 of the writer 0x5f2050: 0xf86b00 (31,166,31), 0xf86b24 (37,198,37), 0xf86b6c (0,23,0 alpha 128)); placed objects use one plain colour over the shipped theme map image where the original gives an object cell the class of its WhichUIType (1 rides, 2 shops, 3 sideshows, 4 to 7 features, 8 track cells), colours it by the ramp 0xf86bd8 (248,0,0) at 0, 0xf86bfc (248,200,0) at 50 and 0xf86c20 (48,252,0) at 100 (0x5f09a0) of the value +0x44 of its object record and outlines it where a neighbour differs (0x5f2380, black or green by +0x68); the base colours are immediates written by 0x5f0700 (black, white, green, yellow, blue (0,78,254), cyan, dark blue (11,66,110) and gradient triples built by 0x5f0970), and the draw 0x5f2380 switches on the cell kind (1 path, 2 queue, 3 object, 8 ...) with the layer mask at +0x18, taking an object cell's colour from 0x5f09a0 over the gradient of the value read from the thing (0x4e0860, 0x4e1e30 by layer mode 2 or 3)", "what the value +0x44 of an object record is (modes 1, 2 and 3 of the layer word +0x20: 0x4e0860, 0x4e1e30), the land modes of the buttons 2444 to 2447 and 2455 to 2457, the track pass 0x5f2fd0, the item dots and footprints (kinds +0x14, 0x5f44d0) and the outline's style argument 8"),
		("UI-091", "the locator panels take staff newest first (by id, descending) and visitors by id, where the original walks the role's thing list (+0x210) and the thing list (0x4824d0); the camera snaps to the followed actor every frame where the original sets the focus directly (0x486860 → 0x42aab0) and the per-frame matrix blend of 0x42b1c0 (weight (1000 - dt) x 0.0005 of the previous frame, dt clamped to 1..1000 ms) smooths it, which OpenTPW's follow does not copy; a staff member's patrol rectangle is not marked (0x536100 in 0x4b3640); the panels appear without sliding and, for a given actor, without the sounds the opener 0x4b3f60 plays (0x11f for a visitor, 0xc6 for staff; the Ctrl+V opener 0x4b4280 without an actor plays none); a picked-up member's state frame 9 (0x485ec0) draws the first frame; the staff window's own locate buttons focus actual actor positions, the list rows' 0x402 path (0x4867b0) is the original's", "the insertion order of the role lists (the thing chain 0x516130/0x516160) and the patrol markers"),
		("UI-092", "the per-employee window (table 0x756f48, 0x4b6080) plays the employee's figure in its portrait frame as the hire window does (0x4b5330 → 0x486530, scale 8.0; UI-082 for the pixel size) where the original's phase comes from a record field (+0xE0) OpenTPW has no counterpart for; a click on the title does not rename (0x48d2e0 holds no rename dialog; the title message 0x10006 goes to a vtable slot +0x38 of the object 0x65e705(0) returns, which is not identified; help 85); the help 0xd4 the window posts while the employee has a patrol area (0x4b5ab0) is not posted; the arrows cycle the economy's member list in hire order for the thing list (0x7cf56c, newest first); the locate button is disabled while the employee has no world position (held in the hand), where 0x4b5f07 always opens the locator panel", "the rename (that vtable slot) and the thing-list order of staff loaded from a save"),
		("UI-094", "the ride view is a first-person eye on the camera car of the coaster train with the smallest position (the car 0x436880 selects) or the carriage's height (prototype), looking along the track or the entry heading; the ride camera never changes the projection (tp.exe builds it once with the argument 90, 0x42a990 and 0x54e860), so its field of view is the park camera's and shares that difference (UI-101: 55 in OpenTPW against 90); the static lasts 0.33 s (video 0.30-0.35 s)", "the static's timer; the field of view is UI-101's"),
